    func createManuscriptRevision(manuscriptId: String, revisionTag: String, snapshotReason: String, author: String) throws  -> SharedItemRow
    
    /**
     * Delete an item by ID.
     *
     * Returns `NotFound` if no item with `id` exists.
     */
