    public static func ==(lhs: SharedItemUpsert, rhs: SharedItemUpsert) -> Bool {
        if lhs.id != rhs.id {
            return false
        }
        if lhs.schemaRef != rhs.schemaRef {
            return false
        }
        if lhs.payloadJson != rhs.payloadJson {
            return false
        }
        if lhs.parentId != rhs.parentId {
